from collections import OrderedDict


class LRUCache:
    """A least-recently-used cache with a fixed capacity.

    Both get() and put() count as a use of the key. When inserting a new key
    would exceed capacity, the least recently used key is evicted first.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        """Return the value for key, or None if absent. Counts as a use."""
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update key. Counts as a use; may evict the LRU key."""
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)
